CREATE TABLE IF NOT EXISTS suggested_order (id INT AUTO_INCREMENT PRIMARY KEY, ticker VARCHAR(12) NOT NULL, side VARCHAR(20) NOT NULL, quantity DECIMAL(18, 6) NOT NULL, suggested_price DECIMAL(18, 6) NULL, status VARCHAR(20) NOT NULL, month_id INT NOT NULL, matched_trade_id INT NULL, executed_quantity DECIMAL(18, 6) NOT NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_suggested_order_month_id__id FOREIGN KEY (month_id) REFERENCES `month`(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_suggested_order_matched_trade_id__id FOREIGN KEY (matched_trade_id) REFERENCES trade(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS transfer_proposal (id INT AUTO_INCREMENT PRIMARY KEY, ticker VARCHAR(12) NOT NULL, month_id INT NOT NULL, from_strategy_id INT NOT NULL, to_strategy_id INT NOT NULL, quantity DECIMAL(18, 6) NOT NULL, amount DECIMAL(18, 6) NULL, auto_approved BOOLEAN NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_transfer_proposal_month_id__id FOREIGN KEY (month_id) REFERENCES `month`(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_transfer_proposal_from_strategy_id__id FOREIGN KEY (from_strategy_id) REFERENCES strategy(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_transfer_proposal_to_strategy_id__id FOREIGN KEY (to_strategy_id) REFERENCES strategy(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
